'use client';
import { useEffect, useState } from 'react';
import { getSupabase } from '../../../lib/supabase';
type User = { id: string; username?: string; email?: string; tier_level?: string };
export default function UsersManager() { const [users, setUsers] = useState<User[]>([]); const [status, setStatus] = useState('Loading users…'); useEffect(() => { (async () => { try { const supabase = getSupabase(); if (!supabase) throw new Error('Supabase is not configured.'); const { data, error } = await supabase.from('profiles').select('id, username, email, tier_level').order('created_at', { ascending: false }); if (error) throw error; setUsers(data ?? []); setStatus(''); } catch (e) { setStatus(e instanceof Error ? e.message : 'Unable to load users.'); } })(); }, []); async function updateTier(id: string, tier_level: string) { try { const supabase = getSupabase(); if (!supabase) throw new Error('Supabase is not configured.'); const { error } = await supabase.from('profiles').update({ tier_level }).eq('id', id); if (error) throw error; setUsers(users.map(u => u.id === id ? { ...u, tier_level } : u)); } catch (e) { setStatus(e instanceof Error ? e.message : 'Unable to update tier.'); } } return <div className="p-5 md:p-8 lg:p-10"><p className="text-xs font-bold uppercase tracking-[.25em] text-cyan">Account operations</p><h1 className="mt-3 text-3xl font-black">Users</h1>{status && <p className="mt-6 text-sm text-muted">{status}</p>}<div className="mt-8 overflow-x-auto rounded-2xl border border-white/10 bg-card"><table className="w-full min-w-[620px] text-left text-sm"><thead className="border-b border-white/10 text-xs uppercase tracking-widest text-muted"><tr><th className="p-5">User</th><th>Email</th><th>Tier</th></tr></thead><tbody>{users.map(user => <tr className="border-b border-white/10 last:border-0" key={user.id}><td className="p-5 font-semibold">{user.username ?? 'Trader'}</td><td className="text-muted">{user.email ?? '—'}</td><td><select value={user.tier_level ?? 'free'} onChange={e => updateTier(user.id, e.target.value)} className="rounded-lg border border-white/10 bg-ink p-2 text-xs"><option value="free">Free</option><option value="pro">Pro</option><option value="elite">Elite</option><option value="whale">Whale</option></select></td></tr>)}</tbody></table></div></div>; }